const getUserMentionOptions = useCallback(
        (personalDetailsParam: PersonalDetailsList | SuggestionPersonalDetailsList, searchValue = ''): Mention[] => {
            const suggestions: Mention[] = [];

            if (CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT.includes(searchValue.toLowerCase())) {
                suggestions.push({
                    text: CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT,
                    alternateText: translate('mentionSuggestions.hereAlternateText'),
                    icons: [
                        {
                            source: Expensicons.Megaphone,
                            type: CONST.ICON_TYPE_AVATAR,
                        },
                    ],
                });
            }
            const participants = ReportUtils.getParticipantsList(currentReport);
            const filteredParticipants = participants.filter((participant) => {
                // If we don't have user's primary login, that member is not known to the current user and hence we do not allow them to be mentioned
                if (!participant?.login || participant.isOptimisticPersonalDetail) {
                    return false;
                }
                // We don't want to mention system emails like notifications@expensify.com
                if (CONST.RESTRICTED_EMAILS.includes(participant.login) || CONST.RESTRICTED_ACCOUNT_IDS.includes(participant.accountID)) {
                    return false;
                }
                const displayName = PersonalDetailsUtils.getDisplayNameOrDefault(participant);
                const displayText = displayName === formatPhoneNumber(participant.login) ? displayName : `${displayName} ${participant.login}`;
                if (searchValue && !displayText.toLowerCase().includes(searchValue.toLowerCase())) {
                    return false;
                }

                // Given the mention is inserted by user, we don't want to show the mention options unless the
                // selection index changes. In that case, suggestionInsertionIndexRef.current will be null.
                // See https://github.com/Expensify/App/issues/38358 for more context
                if (suggestionInsertionIndexRef.current) {
                    return false;
                }

                return true;
            });

            const maxSuggestions = CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_SUGGESTIONS - suggestions.length;
            const sortedParticipants = lodashSortBy(filteredParticipants, (participant) => {
                const weight = ReportUtils.isReportParticipant(participant.accountID, currentReport) ? 0 : 1;
                const displayName = PersonalDetailsUtils.getDisplayNameOrDefault(participant);
                return `${weight}-${displayName.toLowerCase()}`;
            });

            sortedParticipants.slice(0, maxSuggestions).forEach((participant) => {
                suggestions.push({
                    text: formatLoginPrivateDomain(PersonalDetailsUtils.getDisplayNameOrDefault(participant), participant?.login),
                    alternateText: `@${formatLoginPrivateDomain(participant?.login, participant?.login)}`,
                    handle: participant?.login,
                    icons: [
                        {
                            name: participant?.login,
                            source: participant?.avatar ?? Expensicons.FallbackAvatar,
                            type: CONST.ICON_TYPE_AVATAR,
                            fallbackIcon: participant?.fallbackIcon,
                            id: participant?.accountID,
                        },
                    ],
                });
            });

            return suggestions;
        },
        [translate, formatPhoneNumber, formatLoginPrivateDomain, currentReport],
    );

